// Puts the three portals into one shape, and collapses the same house where it
// is listed on more than one of them.

const today = $now.toISODate();

/** Portals write prices as "$549,900", "1.25M", or "From $980,000". */
function toNumber(value) {
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  if (typeof value !== 'string') return null;
  const millions = /([\d.]+)\s*M\b/i.exec(value);
  if (millions) return Math.round(parseFloat(millions[1]) * 1000000);
  const parsed = parseFloat(value.replace(/,/g, '').replace(/[^\d.]/g, ''));
  return Number.isFinite(parsed) && parsed > 0 ? parsed : null;
}

// The Code sandbox does not expose URL. Parsing through it throws on every row
// and the throw is easy to swallow, which loses every listing's link while
// leaving the rest of the row looking fine.
function canonicalUrl(value) {
  if (typeof value !== 'string') return null;
  const withoutQuery = value.trim().split('#')[0].split('?')[0];
  return /^https?:\/\/[^/]+/i.test(withoutQuery) ? withoutQuery.replace(/\/+$/, '') : null;
}

/**
 * The identity of a house, from the parts every portal agrees on.
 *
 * Matching on the listing URL instead would make the same house new again on
 * every portal that carries it, and portals disagree about the tail of an
 * address: one writes "3228 Jewelfish Cove, Austin TX 78728", another glues the
 * city straight on as "3228 Jewelfish CoveAustin, TX 78728". The head never
 * varies, so the key is the street number, the first word of the street, and
 * the ZIP.
 */
function houseKey(address, zip) {
  const head = String(address ?? '').trim().match(/^(\d+)\s+([A-Za-z]+)/);
  return head && zip ? (head[1] + ' ' + head[2] + ' ' + zip).toLowerCase() : null;
}

// A US address ends with its ZIP, so the last five-digit token is the ZIP even
// when the street number is also five digits. The dedicated column cannot be
// trusted ahead of it: the mapper fills it with the street number on some rows.
function toZip(row) {
  const inAddress = String(row.address ?? '').match(/\b\d{5}\b/g);
  if (inAddress) return inAddress[inAddress.length - 1];
  const field = row.zip_code;
  if (typeof field === 'number' && Number.isInteger(field) && field >= 501 && field <= 99950) {
    return String(field).padStart(5, '0');
  }
  const match = String(field ?? '').match(/\b\d{5}\b/);
  return match ? match[0] : null;
}

// One portal runs the city onto the end of the street with no separator, so an
// address cut at the first comma reads "143 Desert Willow WayAustin".
function tidyAddress(value) {
  const spaced = String(value ?? '').replace(/([a-z0-9])([A-Z])/g, '$1 $2').trim();
  return spaced.replace(/\s+/g, ' ');
}

const byKey = new Map();

for (const item of $input.all()) {
  const row = item.json.data ?? item.json;
  const listingUrl = canonicalUrl(row.listing_url);
  const zip = toZip(row);
  const key = houseKey(row.address, zip) ?? listingUrl;
  if (!key || byKey.has(key)) continue;

  const price = toNumber(row.price);
  const sqft = toNumber(row.sqft);

  byKey.set(key, {
    dedupe_key: key,
    listing_url: listingUrl ?? '',
    address: tidyAddress(row.address),
    zip_code: zip ?? '',
    source: listingUrl ? (listingUrl.split('/')[2] || '').replace('www.', '') : '',
    price,
    sqft,
    beds: toNumber(row.beds),
    baths: toNumber(row.baths),
    price_per_sqft: price && sqft ? Math.round(price / sqft) : null,
    first_seen: today,
  });
}

return [...byKey.values()].map((json) => ({ json }));

// Builds the email from the listings that were new this morning.
//
// The first run has no history behind it, so every listing on every portal is
// new — several hundred of them. The table takes all of them, because that is
// what makes the second run meaningful, but the email takes a capped handful:
// an opening edition that runs to hundreds of homes is not read, and it makes
// every ordinary morning afterwards look like nothing happened.

const MAX_IN_EMAIL = 15;

const listings = $input.all().map((item) => item.json);
const shown = listings.slice(0, MAX_IN_EMAIL);

const money = (value) => (value ? '$' + Math.round(Number(value)).toLocaleString('en-US') : 'price not shown');

const lines = shown.map((row) => {
  const size = row.sqft ? row.sqft.toLocaleString('en-US') + ' sqft' : 'size not shown';
  const rooms = [row.beds ? row.beds + ' bed' : null, row.baths ? row.baths + ' bath' : null].filter(Boolean).join(', ');
  const rate = row.price_per_sqft ? ' (' + money(row.price_per_sqft) + '/sqft)' : '';
  return [
    '- ' + (row.address || 'address not shown'),
    '  ' + money(row.price) + rate + ' — ' + [rooms, size].filter(Boolean).join(', '),
    '  ' + (row.zip_code ? 'ZIP ' + row.zip_code + ' · ' : '') + (row.source || 'unknown source'),
    '  ' + (row.listing_url || 'no link'),
  ].join('\n');
});

const bySource = {};
for (const row of listings) bySource[row.source || 'unknown'] = (bySource[row.source || 'unknown'] ?? 0) + 1;

return [
  {
    json: {
      new_count: listings.length,
      shown_count: shown.length,
      capped: listings.length > shown.length,
      sources: Object.entries(bySource).map(([source, count]) => source + ' ' + count).join(', '),
      listings: shown,
      brief: lines.join('\n\n'),
    },
  },
];
